class Solution {
public:
	vector<int> findDisappearedNumbers(vector<int>& nums) {
		auto size = nums.size();
		vector<int> ret;
		for (int i = 0; i < size; i++)
			while (nums[nums[i] - 1] != nums[i])
				swap(nums[nums[i]-1], nums[i]);

		for (int i = 0; i < size; i++)
			if (i+1 != nums[i])
				ret.emplace_back(i+1);
		return ret;
	}
};


